import{_t as e,it as t,n,rt as r}from"./chunks/framework.DJ0NkIPM.js";var i=JSON.parse(`{"title":"Resource Overrides","description":"","frontmatter":{},"headers":[],"relativePath":"zh/qgc-dev-guide/custom_build/resource_override.md","filePath":"zh/qgc-dev-guide/custom_build/resource_override.md"}`),a={name:`zh/qgc-dev-guide/custom_build/resource_override.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="resource-overrides" tabindex="-1">Resource Overrides <a class="header-anchor" href="#resource-overrides" aria-label="Permalink to “Resource Overrides”">​</a></h1><p>A &quot;resource&quot; in QGC source code terminology is anything declared in Qt&#39;s resource system, including:</p><ul><li><a href="https://github.com/mavlink/qgroundcontrol/blob/master/CMakeLists.txt" target="_blank" rel="noreferrer">Root resource declarations</a></li><li>Per-module resources declared via <code>qt_add_resources</code> in the relevant <code>CMakeLists.txt</code> (e.g., under <code>src/</code>)</li><li>QML files</li></ul><p>Overriding a resource allows you to replace it with your own version. This could be as simple as a single icon, or as complex as replacing an entire Vehicle Setup page of UI QML code. Note that using resource overrides means you are duplicating regular QGC source code. This can be a good or a bad thing, depending on how you go about it. By using a resource override on a QML file, for example, allows you to avoid dealing with merge conflicts when merging newer versions of the upstream QGC source. However, it also means that you need to pay attention to the latest version of the QGC source code to see if you need to modify your copied code in a similar way.</p><p>Resource overrides use <code>QQmlEngine::addUrlInterceptor</code> to intercept requests and route them to available custom resources instead of the standard ones. See <a href="https://github.com/mavlink/qgroundcontrol/blob/master/custom-example/src/CustomPlugin.cc" target="_blank" rel="noreferrer">custom-example/src/CustomPlugin.cc</a> for an example you can adapt to your own custom build.</p><p>Custom resources intended as overrides have the prefix <code>/Custom</code> added to their resource name. The file alias should exactly match the standard QGC resource. See the <a href="https://github.com/mavlink/qgroundcontrol/blob/master/custom-example/CMakeLists.txt" target="_blank" rel="noreferrer"><code>qt_add_resources</code> declarations in custom-example/CMakeLists.txt</a> for examples.</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};